"""The typed questions put to each decision model, and how each answer becomes a 0-1 "AI" score."""
from __future__ import annotations

QUESTIONS = {
    "ai_yes": {
        "type": "noul",
        "instructions": "Was this text generated by an AI language model rather than written by a human?",
        "criteria": {"true": "The text was generated by an AI language model.",
                     "false": "The text was written by a human."},
    },
    "author": {
        "type": "choice",
        "instructions": "Who wrote this text?",
        "criteria": {"human": "Written by a human.", "ai": "Generated by an AI language model."},
    },
    "pct_ai": {
        "type": "score",
        "instructions": "What percentage of this text is AI-generated?",
        "criteria": [
            "0% AI-generated: entirely human-written",
            "About 25% AI-generated",
            "About 50% AI-generated",
            "About 75% AI-generated",
            "100% AI-generated: entirely written by an AI language model",
        ],
    },
}


def to_scores(answers: dict) -> dict[str, float]:
    """Map a Clef ``answers`` object to one 0-1 score per question (higher = more likely AI)."""
    top_level = len(QUESTIONS["pct_ai"]["criteria"]) - 1
    return {
        "ai_yes": float(answers["ai_yes"]["noul"]),
        "author": float(answers["author"]["probabilities"]["ai"]),
        "pct_ai": float(answers["pct_ai"]["score"]) / top_level,
    }
